BEGIN;
INSERT INTO public.admin_users(id,email,password_hash,role,is_active)VALUES('b1300000-0000-4000-8000-000000000001','fictional-upload-owner@example.test','fictional-proof','admin',true);
DO $$ DECLARE a uuid:='b1300000-0000-4000-8000-000000000001';f uuid;v uuid;field uuid:=gen_random_uuid();u uuid;again uuid;s uuid;access uuid;doc jsonb;inspected jsonb;BEGIN
 INSERT INTO public.admin_sessions(admin_user_id,token_hash)VALUES(a,repeat('a',64))RETURNING id INTO s;
 INSERT INTO public.forms(slug,title,owner_id,state,access_mode,draft_definition,settings)VALUES('fictional-upload-replay','Fictional upload replay',a,'Open','public','{}','{}')RETURNING id INTO f;
 INSERT INTO public.form_versions(form_id,version,definition,schema_hash,published_by)VALUES(f,1,jsonb_build_object('fields',jsonb_build_array(jsonb_build_object('id',field,'type','file','maxFiles',1))),repeat('b',64),a)RETURNING id INTO v;
 UPDATE public.forms SET published_version_id=v WHERE id=f;
 doc:=jsonb_build_object('key','quarantine/fictional-replay','filename','fictional.txt','mime','text/plain','bytes',20,'sha256',repeat('c',64));
 inspected:=public.inspect_form_upload_preparation(f,v,field,repeat('d',64),repeat('e',64),repeat('f',64),NULL,NULL,NULL);
 IF(inspected->>'committed')::boolean OR NOT(inspected->>'canRetry')::boolean OR EXISTS(SELECT 1 FROM public.upload_intents WHERE form_id=f) THEN RAISE EXCEPTION 'Unaccepted inspection mutated upload state';END IF;
 u:=public.prepare_form_upload(f,v,field,repeat('d',64),doc,repeat('e',64),repeat('f',64),NULL,NULL,NULL);
 again:=public.prepare_form_upload(f,v,field,repeat('d',64),doc||'{"key":"quarantine/must-not-replace"}',repeat('e',64),repeat('f',64),NULL,NULL,NULL);
 IF u<>again OR(SELECT count(*) FROM public.upload_intents WHERE form_id=f)<>1 OR(SELECT quarantine_key FROM public.upload_intents WHERE id=u)<>'quarantine/fictional-replay' THEN RAISE EXCEPTION 'Identical preparation replay duplicated intent or changed object';END IF;
 inspected:=public.inspect_form_upload_preparation(f,v,field,repeat('d',64),repeat('e',64),repeat('f',64),NULL,NULL,NULL);
 IF NOT(inspected->>'committed')::boolean OR(inspected->>'uploadId')::uuid<>u OR inspected::text LIKE '%quarantine%' OR inspected::text LIKE '%fictional.txt%' OR inspected ? 'url' OR inspected ? 'answers' THEN RAISE EXCEPTION 'Preparation receipt lost original ID or disclosed private content';END IF;
 BEGIN PERFORM public.prepare_form_upload(f,v,field,repeat('d',64),doc,repeat('e',64),repeat('0',64),NULL,NULL,NULL);RAISE EXCEPTION 'Original key changed file metadata';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CONFLICT' THEN RAISE;END IF;END;
 BEGIN PERFORM public.prepare_form_upload(f,v,field,repeat('d',64),doc||'{"key":"quarantine/new-key"}',repeat('1',64),repeat('2',64),NULL,NULL,NULL);RAISE EXCEPTION 'New key bypassed one-file quota';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'UPLOAD_QUOTA' THEN RAISE;END IF;END;
 inspected:=public.inspect_form_upload_preparation(f,v,field,repeat('0',64),repeat('e',64),repeat('f',64),NULL,NULL,NULL);IF(inspected->>'committed')::boolean THEN RAISE EXCEPTION 'Receipt crossed respondent proof';END IF;
 UPDATE public.upload_intents SET expires_at=now()-interval '1 second' WHERE id=u;
 inspected:=public.inspect_form_upload_preparation(f,v,field,repeat('d',64),repeat('e',64),repeat('f',64),NULL,NULL,NULL);IF inspected->>'state'<>'expired' THEN RAISE EXCEPTION 'Pending expired intent looked eligible';END IF;
 UPDATE public.forms SET access_mode='internal' WHERE id=f;
 BEGIN PERFORM public.inspect_form_upload_preparation(f,v,field,repeat('d',64),repeat('e',64),repeat('f',64),NULL,NULL,NULL);RAISE EXCEPTION 'Internal upload receipt bypassed current session';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 PERFORM public.inspect_form_upload_preparation(f,v,field,repeat('d',64),repeat('e',64),repeat('f',64),a,s,NULL);
 UPDATE public.admin_sessions SET revoked_at=now() WHERE id=s;
 BEGIN PERFORM public.inspect_form_upload_preparation(f,v,field,repeat('d',64),repeat('e',64),repeat('f',64),a,s,NULL);RAISE EXCEPTION 'Revoked session inspected accepted upload';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 UPDATE public.forms SET access_mode='invited' WHERE id=f;
 INSERT INTO public.form_access_tokens(form_id,token_type,token_hash,expires_at)VALUES(f,'invited',repeat('3',64),now()+interval '1 hour')RETURNING id INTO access;
 PERFORM public.inspect_form_upload_preparation(f,v,field,repeat('d',64),repeat('e',64),repeat('f',64),NULL,NULL,repeat('3',64));
 UPDATE public.form_access_tokens SET revoked_at=now() WHERE id=access;
 BEGIN PERFORM public.inspect_form_upload_preparation(f,v,field,repeat('d',64),repeat('e',64),repeat('f',64),NULL,NULL,repeat('3',64));RAISE EXCEPTION 'Revoked access inspected accepted upload';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 UPDATE public.forms SET access_mode='public' WHERE id=f;
 UPDATE public.idempotency_keys SET expires_at=now()-interval '1 second' WHERE scope LIKE 'form-upload-prepare:'||f||':%';
 BEGIN PERFORM public.inspect_form_upload_preparation(f,v,field,repeat('d',64),repeat('e',64),repeat('f',64),NULL,NULL,NULL);RAISE EXCEPTION 'Expired receipt accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_STATE' THEN RAISE;END IF;END;
 IF has_function_privilege('anon','public.inspect_form_upload_preparation(uuid,uuid,uuid,text,text,text,uuid,uuid,text)','EXECUTE') OR has_function_privilege('authenticated','public.prepare_form_upload(uuid,uuid,uuid,text,jsonb,text,text,uuid,uuid,text)','EXECUTE') OR NOT has_function_privilege('service_role','public.prepare_form_upload(uuid,uuid,uuid,text,jsonb,text,text,uuid,uuid,text)','EXECUTE') THEN RAISE EXCEPTION 'Upload replay privileges wrong';END IF;
END $$;
ROLLBACK;
